import { Lightning } from '@lightningjs/sdk'
import { COLORS, TYPOGRAPHY } from '../constants/colors.js'

export default class StatusDisplay extends Lightning.Component {
  static _template() {
    return {
      w: 1920,
      h: 936,
      alpha: 0,

      Container: {
        mount: 0.5,
        x: 960,
        y: 440,

        AccentBar: {
          mount: 0.5,
          x: 0,
          y: -48,
          w: 64,
          h: 6,
          rect: true,
          color: COLORS.NETFLIX_RED,
        },

        Message: {
          mountX: 0.5,
          x: 0,
          y: -16,
          text: {
            text: '',
            fontSize: 30,
            fontStyle: 'bold',
            fontFace: TYPOGRAPHY.FONT_FAMILY,
            textColor: COLORS.TEXT_WHITE,
            textAlign: 'center',
          },
        },

        SubMessage: {
          mountX: 0.5,
          x: 0,
          y: 34,
          text: {
            text: '',
            fontSize: 20,
            fontFace: TYPOGRAPHY.FONT_FAMILY,
            textColor: COLORS.TEXT_GRAY,
            textAlign: 'center',
          },
        },
      },
    }
  }

  _init() {
    this._pulseAnim = this.tag('Container.AccentBar').animation({
      duration: 1.1,
      repeat: -1,
      actions: [
        { p: 'w', v: { 0: 48, 0.5: 140, 1: 48 } },
        { p: 'alpha', v: { 0: 0.5, 0.5: 1, 1: 0.5 } },
      ],
    })
  }

  _detach() {
    if (this._pulseAnim) {
      this._pulseAnim.stop()
    }
  }

  set status(data) {
    const {
      isFetching,
      isLoading,
      hasChannels,
      hasFilteredChannels,
      searchText,
      hasActiveFilters,
    } = data

    const loading = Boolean(isFetching || isLoading)

    if (loading) {
      this.alpha = 1
      this.tag('Container.Message').text.text = 'Cargando programación en vivo...'
      this.tag('Container.SubMessage').text.text =
        'Verificando señales activas y depurando transmisiones'
      if (this._pulseAnim && !this._pulseAnim.isPlaying()) {
        this._pulseAnim.start()
      }
    } else if (!hasChannels && (searchText || hasActiveFilters || !hasFilteredChannels)) {
      if (this._pulseAnim) this._pulseAnim.stop()
      this.tag('Container.AccentBar').w = 64
      this.tag('Container.AccentBar').alpha = 1
      this.alpha = 1
      this.tag('Container.Message').text.text = 'No encontramos canales con esos filtros'
      this.tag('Container.SubMessage').text.text =
        'Probá limpiar la búsqueda o cambiar la provincia seleccionada en el menú superior.'
    } else if (!hasChannels) {
      if (this._pulseAnim) this._pulseAnim.stop()
      this.alpha = 1
      this.tag('Container.Message').text.text = 'No se pudieron obtener los canales'
      this.tag('Container.SubMessage').text.text =
        'Seleccioná "Actualizar" en la barra superior para reintentar.'
    } else {
      if (this._pulseAnim) this._pulseAnim.stop()
      this.alpha = 0
    }
  }
}
