import { Lightning } from '@lightningjs/sdk'
import { COLORS, TYPOGRAPHY, BORDER_RADIUS } from '../constants/colors.js'

const ITEM_H = 58
const POOL_SIZE = 12
const VISIBLE_COUNT = 10

class SelectItem extends Lightning.Component {
  static _template() {
    return {
      w: 680,
      h: 52,
      rect: true,
      color: COLORS.TRANSPARENT,
      shader: { type: Lightning.shaders.RoundedRectangle, radius: BORDER_RADIUS.MEDIUM },
      Label: {
        x: 24,
        mountY: 0.5,
        y: 27,
        text: {
          text: '',
          fontSize: TYPOGRAPHY.FONT_SIZE_NORMAL,
          fontFace: TYPOGRAPHY.FONT_FAMILY,
          textColor: COLORS.TEXT_LIGHT,
          wordWrapWidth: 632,
          maxLines: 1,
          textOverflow: 'ellipsis',
        },
      },
    }
  }

  set item(v) {
    this._value = v.value
    this._isCurrent = Boolean(v.isCurrent)
    this.tag('Label').text.text = this._isCurrent ? `✓  ${v.label}` : v.label
    this._syncVisual()
  }

  _syncVisual() {
    if (this.hasFocus()) {
      this.patch({
        color: COLORS.FOCUS_WHITE,
        Label: {
          text: {
            textColor: COLORS.BG_BLACK,
            fontStyle: 'bold',
          },
        },
      })
    } else if (this._isCurrent) {
      this.patch({
        color: 0xff2c1215,
        Label: {
          text: {
            textColor: COLORS.TEXT_WHITE,
            fontStyle: 'bold',
          },
        },
      })
    } else {
      this.patch({
        color: COLORS.TRANSPARENT,
        Label: {
          text: {
            textColor: COLORS.TEXT_LIGHT,
            fontStyle: 'normal',
          },
        },
      })
    }
  }

  _focus() {
    this._syncVisual()
  }

  _unfocus() {
    this._syncVisual()
  }

  _handleEnter() {
    this.fireAncestors('$onOptionSelected', this._value)
    return true
  }
}

export default class SelectModal extends Lightning.Component {
  static _template() {
    return {
      w: 1920,
      h: 1080,
      Background: {
        w: 1920,
        h: 1080,
        rect: true,
        color: 0xd908080a,
      },
      Container: {
        x: 960,
        y: 540,
        mount: 0.5,
        w: 760,
        h: 760,
        rect: true,
        color: COLORS.BG_DARK,
        shader: {
          type: Lightning.shaders.RoundedRectangle,
          radius: BORDER_RADIUS.LARGE,
          stroke: 2,
          strokeColor: COLORS.BORDER_LIGHT,
        },
        AccentLine: {
          x: 40,
          y: 34,
          w: 6,
          h: 34,
          rect: true,
          color: COLORS.NETFLIX_RED,
        },
        Title: {
          x: 60,
          y: 30,
          text: {
            text: 'Seleccionar',
            fontSize: 32,
            fontStyle: 'bold',
            fontFace: TYPOGRAPHY.FONT_FAMILY,
            textColor: COLORS.TEXT_WHITE,
          },
        },
        Counter: {
          x: 720,
          y: 38,
          mountX: 1,
          text: {
            text: '',
            fontSize: 18,
            fontFace: TYPOGRAPHY.FONT_FAMILY,
            textColor: COLORS.TEXT_GRAY,
          },
        },
        ListBounds: {
          x: 40,
          y: 96,
          w: 680,
          h: VISIBLE_COUNT * ITEM_H,
          clipping: true,
          Slider: { y: 0, Items: {} },
        },
        FooterHint: {
          x: 380,
          y: 714,
          mountX: 0.5,
          text: {
            text: '▲ ▼  Desplazar     •     OK  Confirmar     •     ↩ ATRÁS  Cancelar',
            fontSize: 17,
            fontFace: TYPOGRAPHY.FONT_FAMILY,
            textColor: COLORS.TEXT_MUTED,
          },
        },
      },
    }
  }

  _construct() {
    this._index = 0
    this._optionsData = []
    this._onSelect = null
    this._pool = null
  }

  _init() {
    const nodes = []
    for (let i = 0; i < POOL_SIZE; i++) {
      nodes.push({ type: SelectItem, alpha: 0, y: -9999 })
    }
    this.tag('Container.ListBounds.Slider.Items').children = nodes
    this._pool = this.tag('Container.ListBounds.Slider.Items').children
  }

  set config(data) {
    this._onSelect = data.onSelect
    const selectedValue = data.selectedValue !== undefined ? data.selectedValue : null
    this.tag('Container.Title').text.text = data.title || 'Seleccionar'

    this._optionsData = (data.options || []).map((opt) => ({
      ...opt,
      isCurrent: selectedValue !== null && opt.value === selectedValue,
    }))

    const activeIdx = this._optionsData.findIndex((o) => o.isCurrent)
    this._index = activeIdx !== -1 ? activeIdx : 0

    this._pool.forEach((node) => {
      node._currentDataIdx = -1
      node.alpha = 0
      node.y = -9999
    })

    this._updateScroll(true)
  }

  _handleUp() {
    if (this._index > 0) {
      this._index--
      this._updateScroll(false)
      this._refocus()
    }
    return true
  }

  _handleDown() {
    if (this._index < this._optionsData.length - 1) {
      this._index++
      this._updateScroll(false)
      this._refocus()
    }
    return true
  }

  _handleBack() {
    this.fireAncestors('$closeSelectModal')
    return true
  }

  _updateScroll(instant = false) {
    const total = this._optionsData.length
    this.tag('Container.Counter').text.text = total > 0 ? `${this._index + 1} / ${total}` : ''

    if (total === 0) return

    const maxScrollIdx = Math.max(0, total - VISIBLE_COUNT)
    const topIdx = Math.max(0, Math.min(maxScrollIdx, this._index - 4))
    const targetY = -(topIdx * ITEM_H)

    if (instant) {
      this.tag('Container.ListBounds.Slider').y = targetY
    } else {
      this.tag('Container.ListBounds.Slider').patch({
        smooth: { y: [targetY, { duration: 0.12 }] },
      })
    }

    const startIdx = Math.max(0, topIdx - 1)
    const endIdx = Math.min(total - 1, topIdx + VISIBLE_COUNT)

    this._pool.forEach((node) => {
      if (
        node._currentDataIdx !== -1 &&
        (node._currentDataIdx < startIdx || node._currentDataIdx > endIdx)
      ) {
        node.alpha = 0
        node._currentDataIdx = -1
        node.y = -9999
      }
    })

    for (let i = startIdx; i <= endIdx; i++) {
      const poolIdx = i % POOL_SIZE
      const node = this._pool[poolIdx]
      if (node._currentDataIdx !== i) {
        node.patch({
          y: i * ITEM_H,
          alpha: 1,
          item: this._optionsData[i],
        })
        node._currentDataIdx = i
      }
    }
  }

  _getFocused() {
    if (!this._optionsData || this._optionsData.length === 0) return this
    const poolIdx = this._index % POOL_SIZE
    return this._pool[poolIdx] || this
  }

  $onOptionSelected(value) {
    if (this._onSelect) this._onSelect(value)
  }
}
