import { Lightning } from '@lightningjs/sdk'
import { COLORS, TYPOGRAPHY, BORDER_RADIUS } from '../constants/colors.js'
import { getOptimizedImageUrl } from '../utils.js'

export default class HeroBanner extends Lightning.Component {
  static _template() {
    return {
      w: 1920,
      h: 350,
      clipping: true,
      BaseBg: {
        w: 1920,
        h: 350,
        rect: true,
        color: COLORS.BG_CANVAS,
      },
      ArtworkWrap: {
        x: 840,
        y: 0,
        w: 1080,
        h: 350,
        clipping: true,
        Backdrop: {
          x: 0,
          y: -80,
          w: 1080,
          h: 540,
          alpha: 0,
        },
        LeftGradient: {
          x: 0,
          y: 0,
          w: 520,
          h: 350,
          rect: true,
          colorLeft: COLORS.BG_CANVAS,
          colorRight: 0x00141414,
        },
        RightGradient: {
          x: 900,
          y: 0,
          w: 180,
          h: 350,
          rect: true,
          colorLeft: 0x00141414,
          colorRight: 0xc0141414,
        },
        TopGradient: {
          x: 0,
          y: 0,
          w: 1080,
          h: 70,
          rect: true,
          colorTop: 0xd9141414,
          colorBottom: 0x00141414,
        },
        BottomGradient: {
          x: 0,
          y: 220,
          w: 1080,
          h: 130,
          rect: true,
          colorTop: 0x00141414,
          colorBottom: COLORS.BG_CANVAS,
        },
      },
      Info: {
        x: 64,
        y: 22,
        StatusBadge: {
          h: 30,
          w: 140,
          rect: true,
          color: COLORS.NETFLIX_RED,
          shader: { type: Lightning.shaders.RoundedRectangle, radius: BORDER_RADIUS.SMALL },
          Label: {
            mount: 0.5,
            x: 70,
            y: 16,
            text: {
              text: 'EN VIVO',
              fontSize: 16,
              fontStyle: 'bold',
              fontFace: TYPOGRAPHY.FONT_FAMILY,
              textColor: COLORS.TEXT_WHITE,
            },
          },
        },
        MetaText: {
          x: 156,
          y: 4,
          text: {
            text: '',
            fontSize: 20,
            fontFace: TYPOGRAPHY.FONT_FAMILY,
            textColor: COLORS.TEXT_GRAY,
            maxLines: 1,
            wordWrapWidth: 740,
            textOverflow: 'ellipsis',
          },
        },
        Avatar: {
          x: 0,
          y: 46,
          w: 48,
          h: 48,
          alpha: 0,
          shader: { type: Lightning.shaders.RoundedRectangle, radius: 24 },
        },
        ChannelName: {
          x: 0,
          y: 42,
          text: {
            text: '',
            fontSize: TYPOGRAPHY.FONT_SIZE_HERO,
            fontStyle: 'bold',
            fontFace: TYPOGRAPHY.FONT_FAMILY,
            textColor: COLORS.TEXT_WHITE,
            maxLines: 1,
            wordWrapWidth: 860,
            textOverflow: 'ellipsis',
          },
        },
        Headline: {
          x: 0,
          y: 108,
          text: {
            text: '',
            fontSize: 26,
            fontStyle: 'bold',
            fontFace: TYPOGRAPHY.FONT_FAMILY,
            textColor: COLORS.TEXT_LIGHT,
            maxLines: 2,
            wordWrapWidth: 880,
            lineHeight: 34,
            textOverflow: 'ellipsis',
          },
        },
        Description: {
          x: 0,
          y: 184,
          text: {
            text: '',
            fontSize: 20,
            fontFace: TYPOGRAPHY.FONT_FAMILY,
            textColor: COLORS.TEXT_GRAY,
            maxLines: 2,
            wordWrapWidth: 860,
            lineHeight: 28,
            textOverflow: 'ellipsis',
          },
        },
        CtaHint: {
          x: 0,
          y: 256,
          h: 44,
          w: 380,
          rect: true,
          color: 0x24ffffff,
          shader: { type: Lightning.shaders.RoundedRectangle, radius: BORDER_RADIUS.MEDIUM },
          Label: {
            mountY: 0.5,
            x: 18,
            y: 23,
            text: {
              text: '▶  Presioná OK para reproducir',
              fontSize: 20,
              fontStyle: 'bold',
              fontFace: TYPOGRAPHY.FONT_FAMILY,
              textColor: COLORS.TEXT_WHITE,
            },
          },
        },
      },
    }
  }

  _init() {
    this._backdropTimer = null
    this._currentBackdropSrc = ''

    this.tag('ArtworkWrap.Backdrop').on('txLoaded', () => {
      this.tag('ArtworkWrap.Backdrop').patch({ smooth: { alpha: 0.85 } })
    })

    this.tag('ArtworkWrap.Backdrop').on('txError', () => {
      this.tag('ArtworkWrap.Backdrop').alpha = 0
    })

    this.tag('Info.Avatar').on('txLoaded', () => {
      this.tag('Info.Avatar').alpha = 1
    })

    this.tag('Info.Avatar').on('txError', () => {
      this.tag('Info.Avatar').alpha = 0
    })
  }

  _detach() {
    if (this._backdropTimer) {
      clearTimeout(this._backdropTimer)
      this._backdropTimer = null
    }
  }

  set featured(data) {
    if (!data || !data.channel) {
      this.alpha = 0
      return
    }

    this.alpha = 1
    const { channel, provinceName = '' } = data
    const actives = channel.ActiveList || Object.values(channel.Actives || {})
    const mainActive = actives.length > 0 ? actives[0] : null
    const isLive = Boolean(mainActive)
    const isPremiere = Boolean(mainActive && mainActive.IsPremiere)

    // 1. Badge de estado
    let badgeText = 'ON DEMAND'
    let badgeColor = COLORS.BG_ELEVATED
    let badgeW = 144

    if (isLive) {
      badgeText = isPremiere ? '★ ESTRENO' : '● EN VIVO'
      badgeColor = isPremiere ? COLORS.PREMIERE_BADGE : COLORS.NETFLIX_RED
      badgeW = isPremiere ? 136 : 128
    }

    this.tag('Info.StatusBadge').patch({
      w: badgeW,
      color: badgeColor,
      Label: {
        x: badgeW / 2,
        text: { text: badgeText },
      },
    })

    // 2. Línea de ubicación y cantidad de señales
    const metaParts = []
    if (channel.ChannelCity) {
      metaParts.push(
        provinceName && provinceName !== channel.ChannelCity
          ? `${channel.ChannelCity}, ${provinceName}`
          : channel.ChannelCity,
      )
    }
    if (actives.length > 1) {
      metaParts.push(`${actives.length} transmisiones en simultáneo`)
    } else if (!isLive) {
      const upcomingCount = channel.Upcoming ? Object.keys(channel.Upcoming).length : 0
      if (upcomingCount > 0) {
        metaParts.push(`${upcomingCount} próximas en guía`)
      }
    }

    this.tag('Info.MetaText').patch({
      x: badgeW + 16,
      text: { text: metaParts.join('  •  ') },
    })

    // 3. Avatar + Nombre del canal
    const avatarUrl = channel.ChannelImgUrl ? getOptimizedImageUrl(channel.ChannelImgUrl, 120) : ''
    if (avatarUrl) {
      if (this._lastAvatarUrl !== avatarUrl) {
        this._lastAvatarUrl = avatarUrl
        this.tag('Info.Avatar').alpha = 0.001
        this.tag('Info.Avatar').src = avatarUrl
      }
      this.tag('Info.ChannelName').x = 62
    } else {
      this._lastAvatarUrl = ''
      this.tag('Info.Avatar').alpha = 0
      this.tag('Info.ChannelName').x = 0
    }
    this.tag('Info.ChannelName').text.text = channel.ChannelName || ''

    // 4. Título de transmisión actual y descripción
    if (isLive) {
      this.tag('Info.Headline').text.text = mainActive.Title || 'Transmisión en directo'
      this.tag('Info.Description').text.text =
        channel.ChannelDescription || 'Señal de streaming en vivo.'
    } else {
      this.tag('Info.Headline').text.text =
        channel.ChannelDescription || 'Explorá los programas y emisiones recientes de este canal.'
      this.tag('Info.Description').text.text = channel.ChannelCity
        ? `Canal de streaming desde ${channel.ChannelCity}.`
        : 'Disponible bajo demanda en YouTube.'
    }

    // 5. Indicador de acción (100% interno en la app)
    let ctaText = '▶  OK para ver en vivo'
    if (actives.length > 1) {
      ctaText = `▶  OK para elegir transmisión (${actives.length})`
    } else if (!isLive) {
      ctaText = '📅  OK para ver transmisiones del canal'
    }
    const ctaW = Math.max(290, ctaText.length * 11 + 36)
    this.tag('Info.CtaHint').patch({
      w: ctaW,
      Label: { text: { text: ctaText } },
    })

    // 6. Imagen de fondo con debounce corto para no saturar WebGL al hacer scroll rápido
    const rawBackdrop =
      (mainActive && mainActive.ThumbnailUrl) ||
      (channel.ChannelBannerUrl
        ? `${channel.ChannelBannerUrl}=w1280-fcrop64=1,00005a57ffffa5a8-k-c0xffffffff-no-nd-rj`
        : channel.ChannelImgUrl || '')

    const nextSrc = rawBackdrop
      ? getOptimizedImageUrl(rawBackdrop, 720, mainActive ? channel.LastActivityAt : '')
      : ''

    if (this._backdropTimer) {
      clearTimeout(this._backdropTimer)
      this._backdropTimer = null
    }

    if (!nextSrc) {
      this._currentBackdropSrc = ''
      this.tag('ArtworkWrap.Backdrop').alpha = 0
      return
    }

    if (this._currentBackdropSrc === nextSrc) return

    this._backdropTimer = setTimeout(() => {
      this._currentBackdropSrc = nextSrc
      this.tag('ArtworkWrap.Backdrop').alpha = 0.001
      this.tag('ArtworkWrap.Backdrop').src = nextSrc
    }, 90)
  }
}
