import { Lightning } from '@lightningjs/sdk'
import { COLORS, TYPOGRAPHY, BORDER_RADIUS } from '../constants/colors.js'

export default class TVPlayer extends Lightning.Component {
  static _template() {
    return {
      w: 1920,
      h: 1080,
      rect: true,
      color: COLORS.TRANSPARENT,

      Controls: {
        x: 64,
        y: 48,
        alpha: 1,
        w: 640,
        h: 60,
        rect: true,
        color: 0xe6101014,
        shader: {
          type: Lightning.shaders.RoundedRectangle,
          radius: BORDER_RADIUS.MEDIUM,
          stroke: 2,
          strokeColor: 0x44ffffff,
        },
        RedAccent: {
          x: 0,
          y: 12,
          w: 5,
          h: 36,
          rect: true,
          color: COLORS.NETFLIX_RED,
        },
        Text: {
          mount: 0.5,
          x: 320,
          y: 31,
          text: {
            text: '↩ Volver   •   OK: Pausar   •   ◀ 15s ▶',
            fontSize: 22,
            fontStyle: 'bold',
            fontFace: TYPOGRAPHY.FONT_FAMILY,
            textColor: COLORS.TEXT_WHITE,
          },
        },
      },
    }
  }

  _init() {
    this._timer = null
    this._isClosing = false
    this._focusInterval = null
    this._isPlaying = true
  }

  _active() {
    this._isClosing = false
    this._createIframe()
    this._wakeUpControls()
  }

  _inactive() {
    this._destroyIframe()
    this._clearTimer()
    this._clearFocusLock()
  }

  set videoId(id) {
    this._videoId = id
    if (this.active) {
      this._destroyIframe()
      this._createIframe()
    }
  }

  set onClose(callback) {
    this._onCloseCallback = callback
  }

  _createIframe() {
    if (this._iframe || !this._videoId) return

    this._currentTime = 0
    this._duration = 0

    this._messageListener = (event) => {
      try {
        const data = JSON.parse(event.data)
        if (data.event === 'infoDelivery' && data.info) {
          if (data.info.currentTime !== undefined) this._currentTime = data.info.currentTime
          if (data.info.duration !== undefined) this._duration = data.info.duration
        }
      } catch (err) {
        // Ignorar mensajes externos que no sean JSON
      }
    }
    window.addEventListener('message', this._messageListener)

    const isRemoteHttps =
      window.location &&
      window.location.protocol === 'https:' &&
      window.location.hostname !== 'localhost'
    const originParam = isRemoteHttps ? `&origin=${encodeURIComponent(window.location.origin)}` : ''

    this._iframe = document.createElement('iframe')
    this._iframe.className = 'tv-iframe'
    this._iframe.src = `https://www.youtube-nocookie.com/embed/${this._videoId}?autoplay=1&fs=1&modestbranding=1&rel=0&enablejsapi=1${originParam}`
    this._iframe.frameBorder = '0'
    this._iframe.referrerPolicy = 'strict-origin-when-cross-origin'
    this._iframe.allow =
      'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture'
    this._iframe.allowFullscreen = true

    this._iframe.style.position = 'absolute'
    this._iframe.style.top = '0'
    this._iframe.style.left = '0'
    this._iframe.style.width = '100vw'
    this._iframe.style.height = '100vh'
    this._iframe.style.zIndex = '0'
    this._iframe.style.border = 'none'

    this._iframe.onload = () => {
      if (this._iframe && this._iframe.contentWindow) {
        this._iframe.contentWindow.postMessage(JSON.stringify({ event: 'listening' }), '*')
      }
    }

    document.body.appendChild(this._iframe)
    this._isPlaying = true
    this._updateControlsText()
  }

  _destroyIframe() {
    if (this._messageListener) {
      window.removeEventListener('message', this._messageListener)
      this._messageListener = null
    }

    if (this._iframe) {
      if (this._iframe.contentWindow) {
        this._iframe.contentWindow.postMessage(
          JSON.stringify({ event: 'command', func: 'stopVideo', args: [] }),
          '*',
        )
      }

      if (this._iframe.parentNode) {
        this._iframe.parentNode.removeChild(this._iframe)
      }
      this._iframe = null
    }
    this._clearFocusLock()
  }

  _clearFocusLock() {
    if (this._focusInterval) {
      clearInterval(this._focusInterval)
      this._focusInterval = null
    }
  }

  _wakeUpControls() {
    this.tag('Controls').alpha = 1
    this._clearTimer()

    this._timer = setTimeout(() => {
      this.tag('Controls').patch({
        smooth: { alpha: 0 },
      })
      this._timer = null
    }, 4000)
  }

  _clearTimer() {
    if (this._timer) {
      clearTimeout(this._timer)
      this._timer = null
    }
  }

  _updateControlsText() {
    const textNode = this.tag('Controls.Text')
    if (this._isPlaying) {
      textNode.text.text = '↩ Volver   •   OK: Pausar   •   ◀ 15s ▶'
    } else {
      textNode.text.text = '⏸ PAUSADO   •   OK: Reproducir   •   ↩ Volver'
    }
  }

  _handleBack() {
    if (this._isClosing) return true
    this._isClosing = true

    if (this._onCloseCallback) {
      this._onCloseCallback()
    }

    return true
  }

  _handleEnter() {
    this._isPlaying = !this._isPlaying

    if (this._iframe && this._iframe.contentWindow) {
      const command = this._isPlaying ? 'playVideo' : 'pauseVideo'
      this._iframe.contentWindow.postMessage(
        JSON.stringify({
          event: 'command',
          func: command,
          args: [],
        }),
        '*',
      )
    }

    this._updateControlsText()
    this._wakeUpControls()
    return true
  }

  _handleLeft() {
    this._seek(-15)
    return true
  }

  _handleRight() {
    this._seek(15)
    return true
  }

  _seek(seconds) {
    if (this._iframe && this._iframe.contentWindow) {
      this._currentTime = Math.max(0, this._currentTime + seconds)
      if (this._duration > 0) {
        this._currentTime = Math.min(this._currentTime, this._duration)
      }

      this._iframe.contentWindow.postMessage(
        JSON.stringify({ event: 'command', func: 'seekTo', args: [this._currentTime, true] }),
        '*',
      )
      this._wakeUpControls()
    }
  }

  _handleKey() {
    this._wakeUpControls()
    return false
  }
}
