import { Lightning } from '@lightningjs/sdk'
import { COLORS, TYPOGRAPHY } from '../constants/colors.js'

export default class AppFooter extends Lightning.Component {
  static _template() {
    return {
      w: 1920,
      h: 48,
      rect: true,
      color: 0xeb0b0b0e,
      TopLine: {
        w: 1920,
        h: 1,
        rect: true,
        color: 0x1fffffff,
      },
      Hints: {
        x: 64,
        y: 25,
        mountY: 0.5,
        text: {
          text: 'OK  Seleccionar     •     ◀ ▶ ▲ ▼  Navegar     •     ↩ ATRÁS  Menú superior',
          fontSize: 18,
          fontFace: TYPOGRAPHY.FONT_FAMILY,
          textColor: COLORS.TEXT_GRAY,
        },
      },
      Stats: {
        x: 1856,
        y: 25,
        mountX: 1,
        mountY: 0.5,
        text: {
          text: '',
          fontSize: 18,
          fontFace: TYPOGRAPHY.FONT_FAMILY,
          textColor: COLORS.TEXT_MUTED,
        },
      },
    }
  }

  set config(data) {
    if (!data) return
    const { viewMode, liveCount = 0, totalCount = 0, isRefreshing = false } = data

    if (viewMode === 'grid') {
      this.tag('Hints').text.text =
        'OK  Ver transmisión / Info canal     •     ◀ ▶  Cambiar horario o día     •     ▲ ▼  Cambiar canal     •     ↩ ATRÁS  Menú'
    } else {
      this.tag('Hints').text.text =
        'OK  Ver transmisión     •     ◀ ▶ ▲ ▼  Explorar catálogo     •     ↩ ATRÁS  Menú superior'
    }

    if (isRefreshing) {
      this.tag('Stats').text.text = 'Actualizando programación...'
    } else if (totalCount > 0) {
      this.tag('Stats').text.text = `${liveCount} en vivo  •  ${totalCount} canales`
    } else {
      this.tag('Stats').text.text = ''
    }
  }
}
