export const getFreshImage = (url, dateString) => {
  if (!url) return ''
  if (!dateString) return url
  const parsed = new Date(dateString).getTime()
  if (isNaN(parsed)) return url
  const separator = url.indexOf('?') !== -1 ? '&' : '?'
  return `${url}${separator}t=${parsed}`
}

export const getOptimizedImageUrl = (url, width = 400, dateString = '') => {
  if (!url) return ''

  let src = url.replace(/(maxresdefault|hqdefault|sddefault)\.jpg/i, 'mqdefault.jpg')
  if (dateString) {
    src = getFreshImage(src, dateString)
  }

  if (
    src.indexOf('ytimg.com') !== -1 ||
    src.indexOf('youtube.com') !== -1 ||
    src.indexOf('ggpht.com') !== -1 ||
    src.indexOf('googleusercontent.com') !== -1
  ) {
    return `https://wsrv.nl/?url=${encodeURIComponent(src)}&w=${width}&output=webp`
  }

  return src
}

export const formatActivityDate = (dateString) => {
  if (!dateString) return ''
  const date = new Date(dateString)
  if (isNaN(date.getTime())) return dateString
  return date.toLocaleString('es-AR', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  })
}

export const formatTimeOnly = (dateString) => {
  if (!dateString) return '--:--'
  const date = new Date(dateString)
  if (isNaN(date.getTime())) return '--:--'
  return date.toLocaleTimeString('es-AR', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  })
}

export const isSameLocalDay = (dateA, dateB) => {
  if (!dateA || !dateB) return false
  return (
    dateA.getFullYear() === dateB.getFullYear() &&
    dateA.getMonth() === dateB.getMonth() &&
    dateA.getDate() === dateB.getDate()
  )
}
